Import ListNotations. Import KXS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Set Warnings "-notation-for-abbreviation".
Notation amem := (word -> option byte).

(* [comment removed for export] *)
Definition z4s_src_ctx (RNG : footprint) (mm : amem) (SS n SBL SBH : Z) : Prop :=
  mem_inv asegs mm
  /\ (exists sbuf, bytes_at asegs mm SS sbuf /\ Z.of_nat (length sbuf) = n)
  /\ unpoisoned mm SBL SBH /\ SBL <= SS /\ SS + n <= SBH /\ SBL mod 8 = 0
  /\ rng RNG SS n /\ rng RNG (shad SBL) (shlen (SBH - SBL + 7)) /\ rng_aimg RNG
  /\ 0x60d000 <= SS /\ SS + n <= 2^47 /\ 0x60d000 <= SBL /\ SBH <= 2^47.

Ltac z4s_src_intro C :=
  let MI := fresh "MI" in let sbuf := fresh "sbuf" in let SB := fresh "SB" in let SL := fresh "SL" in
  destruct C as (MI & (sbuf & SB & SL) & ?US & ?US1 & ?US2 & ?A8 & ?WS & ?WSS & ?WI & ?R1 & ?R2 & ?R3 & ?R4).

Definition z4s_B1_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x19 x20 x21 x22 x23 x24 x25 x26 x28 x29 x30 x31 : word)
         (SP SS n SBL SBH E lo : Z),
    z4s_src_ctx RNG mm SS n SBL SBH ->
    ztab_fact asegs mm (E - 1) 1 1 [(0, 1, 255)] ->
    SS + 8 <= E <= SS + n ->
    stk asegs mm lo (SP + -104) -> lo <= SP + -576 -> rng RNG (SP + -576) 576 ->
    0x10007fff8000 <= SP + -576 -> SP <= 2^47 -> SS + n <= SP + -576 ->
    (forall (r : Z) (a5 a6 a7 : word) (mm' : amem), 1 <= r <= 255 ->
       munch [(SP + -536, SP + -528)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' -> stk asegs mm' lo (SP + -104) ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 (SP + -576)) gp tp x5 x6 x7 x8 x9 (Z_to_bv 64 (E + -1)) (Z_to_bv 64 r) x12
                                 x13 x14 a5 a6 a7 (Z_to_bv 64 E) x19 x20 x21 x22 x23 x24 x25 (Z_to_bv 64 (E + -8))
                                 (Z_to_bv 64 2147450880) x28 x29 x30 x31)
                            F (Z_to_bv 64 0x87e88) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 (SP + -576)) gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 (Z_to_bv 64 E)
                             x19 x20 x21 x22 x23 x24 x25 x26 (Z_to_bv 64 2147450880) x28 x29 x30 x31)
                        F (Z_to_bv 64 0x87e40) fc None mm (seg_rom asegs)).

